<div id="tw-asana-work" class="teams-asana-list" aria-label="Live Asana work"></div>
<dialog id="tw-asana-picker" aria-labelledby="tw-asana-picker-heading">
    <h2 id="tw-asana-picker-heading">Bring your Asana work into focus</h2><p class="muted">Connect your own account. Only you can see your selected Asana work here. Changes stay in Asana.</p>
    <p id="tw-asana-connection-status" role="status"></p><p id="tw-asana-setup" class="teams-source-error" hidden>Your workspace administrator needs to finish the Asana app setup.</p>
    <div class="actions"><button id="tw-asana-connect" type="button" class="primary">Connect Asana</button><button id="tw-asana-choose" type="button" hidden>Choose projects</button><button id="tw-asana-disconnect" type="button" hidden>Disconnect my account</button></div>
    <label>Asana workspace<select id="tw-asana-workspace"></select></label><button id="tw-asana-workspaces-more" type="button" hidden>More workspaces</button><label>Find a project<input id="tw-asana-project-query" type="search" placeholder="Search loaded projects"></label><label><span><input id="tw-asana-archive" type="checkbox"> Browse archived projects</span></label>
    <p id="tw-asana-picker-status" class="muted" role="status"></p><div id="tw-asana-catalog" class="teams-asana-projects"></div>
    <div class="actions"><button id="tw-asana-catalog-more" type="button" hidden>Load more projects</button><button id="tw-asana-save-selection" type="button" class="primary" hidden>Use selected projects</button><button id="tw-asana-close" type="button">Close</button></div>
</dialog>
<dialog id="tw-asana-detail" class="teams-asana-detail" aria-label="Asana task details"><button id="tw-asana-detail-close" type="button">Close task details</button><div id="tw-asana-detail-body"></div></dialog>
